      data: {
        schema: 'comet.native.status.v2',
        migrationRequired: true,
        continuation: { disposition: 'blocked' },
      },
    });
    const migrated = json(
      await runNativeCli([
        'next',
        'legacy-change',
        '--summary',
        'Resume from the portable stable boundary',
        '--json',
