import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { runNativeCli } from '../../../domains/comet-native/native-cli.js';
import { buildNativePortableAcceptance } from '../../../domains/comet-native/native-portable-acceptance.js';
import {
  defaultProjectConfig,
  writeProjectConfig,
} from '../../../domains/comet-native/native-config.js';

const brief = `# Outcome
Correct the greeting.
# Scope
Change the greeting only.
## Directory structure
### Created
None.
### Modified
- README.md — correct the greeting sentence.
### Deleted
None.
### Not created
None.
# Non-goals
None.
# Acceptance examples
- The greeting reads hello.
# Constraints and invariants
Preserve the command usage.
# Decisions
No product behavior change: correct documentation spelling only.
# Open questions
None.
# Verification expectations
Inspect the changed text.
`;

describe('Native workflow friction regressions', () => {
  let root: string;
  let changeDir: string;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-flow-friction-'));
    execFileSync('git', ['init', '--quiet'], { cwd: root });
    const config = defaultProjectConfig('docs', 'en');
    await writeProjectConfig(root, {
      ...config,
      native: { ...config.native, document_writes: 'revert' },
    });
    await command(['new', 'tiny', '--runtime', 'compat', '--language', 'en']);
    changeDir = path.join(root, 'docs', 'comet', 'changes', 'tiny');
  });

  afterEach(async () => {
    await fs.rm(root, { recursive: true, force: true });
  });

  async function command(args: string[]) {
    const result = await runNativeCli([...args, '--project-root', root, '--json']);
    return JSON.parse(result.stdout!) as {
      exitCode: number;
      summary?: string;
      error?: { code: string; message: string };
      data?: { state: { phase: string; state_version: number }; continuation: unknown };
      agent?: { phase: string; stateVersion: number };
    };
  }

  async function confirm(source = brief) {
    await fs.writeFile(path.join(changeDir, 'brief.md'), source);
    const prepared = await command([
      'next',
      'tiny',
      '--summary',
      'Correct documentation spelling.',
    ]);
    expect(prepared.exitCode).toBe(0);
    const confirmed = await command([
      'next',
      'tiny',
      '--confirmed',
      '--summary',
      'User confirmed the complete Shape.',
      '--expected-state-version',
      String(prepared.agent!.stateVersion),
      '--expected-action',
      'confirm-shape',
    ]);
    expect(confirmed.agent?.phase).toBe('build');
    return confirmed;
  }

  async function input(value: unknown) {
    const file = `${root}-input.json`;
    await fs.writeFile(file, JSON.stringify(value));
    try {
      return await command(['next', 'tiny', '--runner-input', file]);
    } finally {
      await fs.rm(file, { force: true });
    }
  }

  it('accepts a focused four-section brief without inventing optional material', async () => {
    await fs.writeFile(
      path.join(changeDir, 'brief.md'),
      `# Outcome
Correct documentation spelling.
# Scope
README only. No product behavior change: correct a spelling mistake.
## Directory structure
### Created
None.
### Modified
- README.md — correct the spelling mistake.
### Deleted
None.
### Not created
None.
# Non-goals
None.
# Acceptance examples
- README spells hello correctly.
`,
    );
    const prepared = await command(['next', 'tiny', '--summary', 'Correct the README spelling.']);
    expect(prepared.exitCode).toBe(0);
    expect(prepared.agent?.phase).toBe('shape');
  });

  it('keeps the confirmed goal when only spacing around headings changes', async () => {
    const confirmed = await confirm();
    await fs.writeFile(
      path.join(changeDir, 'brief.md'),
      brief.replace('# Scope\n', '\n# Scope\n\n'),
    );
    const current = await command(['next', 'tiny', '--summary', 'Continue the confirmed work.']);
    expect(current.exitCode).toBe(0);
    expect(current.agent?.phase).toBe('build');
    expect(current.agent?.stateVersion).toBe(confirmed.agent?.stateVersion);
  });

  it('returns the current Builder action on recovery without advancing the phase', async () => {
    const confirmed = await confirm();
    const current = await command(['next', 'tiny', '--summary', 'Resume the current task.']);
    expect(current.exitCode).toBe(0);
    expect(current.agent).toMatchObject({
      phase: 'build',
      stateVersion: confirmed.agent!.stateVersion,
    });
    expect(current.data?.continuation).toMatchObject({ action: 'builder-handoff' });
  });

  it('dispatches directly after the explicit handoff plan and includes small acceptance scopes', async () => {
    await confirm();
    const inputFile = `${root}-handoff.json`;
    await fs.writeFile(
      inputFile,
      JSON.stringify({
        kind: 'builder-handoff',
        summary: 'Corrected the documentation spelling.',
        addressed_acceptance_ids: ['A1'],
        acceptance_review: [
          {
            id: 'A1',
            status: 'implemented-with-evidence',
            evidence: ['README contains hello.'],
            note: 'Matches the confirmed spelling.',
          },
        ],
        checks: [],
        known_limits: [],
        verification_checks: [],
      }),
    );
    try {
      const result = await command(['next', 'tiny', '--runner-input', inputFile]);
      const packet = (
        result.data as unknown as {
          verifierDispatch: { acceptance: unknown; startupInput: unknown };
        }
      ).verifierDispatch;
      expect(result.exitCode).toBe(0);
      expect(packet).toMatchObject({
        acceptance: [{ id: 'A1', text: 'The greeting reads hello.' }],
        startupInput: { kind: 'verifier-started' },
      });
    } finally {
      await fs.rm(inputFile, { force: true });
    }
  });

  it('keeps the complete scope paginated when it does not fit in the task packet', async () => {
    const examples = Array.from({ length: 17 }, (_, index) => `Behavior ${index + 1} works.`);
    await confirm(
      brief.replace('- The greeting reads hello.', examples.map((text) => `- ${text}`).join('\n')),
    );
    const ids = examples.map((_, index) => `A${index + 1}`);
    const dispatched = await input({
      kind: 'builder-handoff',
      summary: 'Implemented the confirmed scope.',
      addressed_acceptance_ids: ids,
      acceptance_review: ids.map((id) => ({
        id,
        status: 'implemented-with-evidence',
        evidence: [`README documents ${id}.`],
        note: 'Checked the corresponding behavior.',
      })),
      checks: [],
      verification_checks: [],
      known_limits: [],
    });
    expect(dispatched.exitCode).toBe(0);
    const packet = (dispatched.data as unknown as { verifierDispatch: Record<string, unknown> })
      .verifierDispatch;
    expect(packet).not.toHaveProperty('acceptance');
    expect(packet).toMatchObject({ scopeCount: 17, scopeIds: ids });
    expect(packet.detailsPageArgs).toEqual(expect.arrayContaining(['status', '--details']));
  });

  it.each(['A0', 'A01', 'a1', 'A1 A2', ''])(
    'rejects malformed Spec acceptance reference %s',
    (reference) => {
      expect(() =>
        buildNativePortableAcceptance({
          resolveBriefReferences: true,
          briefMarkdown: '# Acceptance examples\n- The greeting reads hello.\n',
          specs: [
            {
              capability: 'greeting',
              source: 'specs/greeting/spec.md',
              markdown: `### Scenario: Greeting\nAcceptance: ${reference}\n`,
            },
          ],
        }),
      ).toThrow(/reference must be one brief ID/iu);
    },
  );

  it('lets a Spec reference a brief criterion without creating a second criterion', () => {
    const acceptance = buildNativePortableAcceptance({
      resolveBriefReferences: true,
      briefMarkdown: '# Acceptance examples\n- The greeting reads hello.\n',
      specs: [
        {
          capability: 'greeting',
          source: 'specs/greeting/spec.md',
          markdown:
            '### Scenario: Greeting spelling\nAcceptance: A1\nWHEN the greeting is displayed\nTHEN it reads hello.\n',
        },
      ],
    });
    expect(acceptance).toEqual([
      { id: 'A1', source: 'brief.md', text: 'The greeting reads hello.' },
    ]);
  });

  it('rejects a Spec reference to a missing brief criterion', () => {
    expect(() =>
      buildNativePortableAcceptance({
        resolveBriefReferences: true,
        briefMarkdown: '# Acceptance examples\n- The greeting reads hello.\n',
        specs: [
          {
            capability: 'greeting',
            source: 'specs/greeting/spec.md',
            markdown: '### Scenario: Greeting\nAcceptance: A2\n',
          },
        ],
      }),
    ).toThrow(/unknown brief acceptance/iu);
  });

  it('keeps previously confirmed Spec reference text as a separate legacy criterion', () => {
    const acceptance = buildNativePortableAcceptance({
      briefMarkdown: '# Acceptance examples\n- The greeting reads hello.\n',
      specs: [
        {
          capability: 'greeting',
          source: 'specs/greeting/spec.md',
          markdown:
            '### Scenario: Greeting\nAcceptance: A1\nWHEN the greeting is displayed\nTHEN it reads hello.\n',
        },
      ],
    });
    expect(acceptance.map(({ id }) => id)).toEqual(['A1', 'A2']);
    expect(acceptance[1].text).toContain('Acceptance: A1');
  });
});

import { describe, expect, it } from 'vitest';

import {
  NATIVE_ACCEPTANCE_EVIDENCE_END_MARKER,
  NATIVE_ACCEPTANCE_EVIDENCE_START_MARKER,
  deriveBriefAcceptanceCriteria,
  deriveSpecAcceptanceCriteria,
  deriveSpecMandatoryAcceptanceCriteria,
  normalizeNativeAcceptanceText,
  parseNativeVerificationMachineBlock,
  projectNativeAcceptancePage,
  serializeNativeVerificationMachineBlock,
} from '../../../domains/comet-native/native-acceptance.js';
import type { NativeAcceptanceCriterion } from '../../../domains/comet-native/native-acceptance.js';

describe('Native acceptance criteria', () => {
  function criterion(index: number, overrides: Partial<NativeAcceptanceCriterion> = {}) {
    return {
      id: `acceptance-${index.toString(16).padStart(64, '0')}`,
      kind: 'brief-example' as const,
      source: 'brief.md',
      context: [],
      text: `Criterion ${index}.`,
      ...overrides,
    };
  }

  it.each([0, 1, 16, 17, 41])(
    'pages %i acceptance criteria without losing or repeating IDs',
    (count) => {
      const criteria = Array.from({ length: count }, (_, index) => criterion(index + 1));
      const acceptanceHash = 'a'.repeat(64);
      const ids: string[] = [];
      let cursor: string | null = null;
      do {
        const page = projectNativeAcceptancePage({ criteria, acceptanceHash, cursor });
        expect(Buffer.byteLength(JSON.stringify(page), 'utf8')).toBeLessThanOrEqual(32 * 1024);
        ids.push(...page.items.map((item) => item.id));
        cursor = page.nextCursor;
      } while (cursor !== null);

      expect(ids).toEqual(criteria.map((item) => item.id));
      expect(new Set(ids).size).toBe(ids.length);
    },
  );

  it('bounds long Unicode text and context without splitting code points', () => {
    const page = projectNativeAcceptancePage({
      acceptanceHash: 'b'.repeat(64),
      criteria: [
        criterion(1, {
          text: '鱼'.repeat(1_000),
          context: ['章'.repeat(500), 'second', 'third', 'fourth', 'fifth'],
        }),
      ],
    });

    expect(Buffer.byteLength(page.items[0].text, 'utf8')).toBeLessThanOrEqual(512);
    expect(page.items[0].text).not.toContain('\uFFFD');
    expect(page.items[0]).toMatchObject({ textTruncated: true, contextTruncated: true });
    expect(page.items[0].context).toHaveLength(4);
    expect(Buffer.byteLength(page.items[0].context[0], 'utf8')).toBeLessThanOrEqual(256);
  });

  it('binds cursors to the acceptance hash and rejects malformed offsets', () => {
    const criteria = Array.from({ length: 17 }, (_, index) => criterion(index + 1));
    const first = projectNativeAcceptancePage({ criteria, acceptanceHash: 'c'.repeat(64) });
    expect(first.nextCursor).not.toBeNull();
    expect(() =>
      projectNativeAcceptancePage({
        criteria,
        acceptanceHash: 'd'.repeat(64),
        cursor: first.nextCursor,
      }),
    ).toThrow('stale');
    expect(() =>
      projectNativeAcceptancePage({
        criteria,
        acceptanceHash: 'c'.repeat(64),
        cursor: `native-acceptance-v1.${'c'.repeat(64)}.00g`,
      }),
    ).toThrow('invalid');
    const tamperedCursor = `${first.nextCursor!.slice(0, -1)}${first.nextCursor!.endsWith('0') ? '1' : '0'}`;
    expect(() =>
      projectNativeAcceptancePage({
        criteria,
        acceptanceHash: 'c'.repeat(64),
        cursor: tamperedCursor,
      }),
    ).toThrow('integrity');
  });

  it('projects bounded prior verification gaps on Build acceptance pages', () => {
    const criteria = Array.from({ length: 3 }, (_, index) => ({
      id: `acceptance-${index.toString(16).padStart(64, '0')}`,
      kind: 'brief-example' as const,
      source: 'brief.md',
      context: [],
      text: `Criterion ${index}.`,
    }));
    const statuses = new Map([
      [criteria[0].id, 'satisfied' as const],
      [criteria[1].id, 'failed' as const],
      [criteria[2].id, 'missing' as const],
    ]);
    const page = projectNativeAcceptancePage({
      criteria,
      acceptanceHash: 'a'.repeat(64),
      verificationStatuses: statuses,
      failedCheckIds: Array.from({ length: 20 }, (_, index) => `check-${index}`),
    });

    expect(page.items.map((item) => item.verificationStatus)).toEqual([
      'satisfied',
      'failed',
      'missing',
    ]);
    expect(page.failedAcceptanceIds).toEqual([criteria[1].id]);
    expect(page.missingAcceptanceIds).toEqual([criteria[2].id]);
    expect(page.failedCheckIds).toHaveLength(16);
    expect(page.failedCheckIdsTruncated).toBe(true);
  });

  it('derives stable IDs from Acceptance examples independent of list order and wrapping', () => {
    const first = `# Outcome
Ship login.

# Acceptance examples
- Valid credentials create a session.
- Invalid credentials are rejected
  without revealing which field failed.

# Constraints and invariants
Keep compatibility.
`;
    const reordered = `# Acceptance examples
- Invalid credentials are rejected without revealing which field failed.
- Valid credentials create a session.
`;

    const firstCriteria = deriveBriefAcceptanceCriteria(first);
    const reorderedCriteria = deriveBriefAcceptanceCriteria(reordered);

    expect(new Set(firstCriteria.map(({ id }) => id))).toEqual(
      new Set(reorderedCriteria.map(({ id }) => id)),
    );
    expect(firstCriteria).toHaveLength(2);
    expect(firstCriteria[0]).toMatchObject({
      kind: 'brief-example',
      source: 'brief.md',
      text: 'Valid credentials create a session.',
    });
  });

  it('normalizes whitespace and canonically equivalent Unicode without folding case', () => {
    expect(normalizeNativeAcceptanceText('  Café\r\n  opens\tfast.  ')).toBe('Café opens fast.');
    expect(normalizeNativeAcceptanceText('Café')).toBe('Café');
    expect(normalizeNativeAcceptanceText('PASS')).not.toBe(normalizeNativeAcceptanceText('pass'));
  });

  it('derives Scenario criteria while ignoring headings inside fenced code', () => {
    const spec = `# Authentication

## Requirement: Password login

### Scenario: Valid credentials
- **WHEN** valid credentials are submitted
- **THEN** a session is created

\`\`\`md
### Scenario: Not a real scenario
\`\`\`

### Scenario: Invalid credentials
- **WHEN** invalid credentials are submitted
- **THEN** access is denied
`;

    const criteria = deriveSpecAcceptanceCriteria(spec, 'specs/authentication/spec.md');

    expect(criteria).toHaveLength(2);
    expect(criteria.map(({ source }) => source)).toEqual([
      'specs/authentication/spec.md',
      'specs/authentication/spec.md',
    ]);
    expect(criteria[0]).toMatchObject({
      kind: 'spec-scenario',
      text: expect.stringContaining('Valid credentials'),
    });
    expect(criteria[0].id).not.toBe(criteria[1].id);
  });

  it('derives mandatory specification bullets even when a spec has no Scenario headings', () => {
    const spec = `# Capability

## Contract

- Runtime MUST bind each requirement to a receipt.
- 失败检查必须阻断归档。
- This explanatory note is not normative.

\`\`\`md
- Runtime MUST ignore this example.
\`\`\`
`;

    expect(deriveSpecMandatoryAcceptanceCriteria(spec, 'specs/capability/spec.md')).toMatchObject([
      {
        kind: 'spec-must',
        source: 'specs/capability/spec.md',
        text: 'Runtime MUST bind each requirement to a receipt.',
      },
      {
        kind: 'spec-must',
        text: '失败检查必须阻断归档。',
      },
      {
        kind: 'spec-must',
        text: 'This explanatory note is not normative.',
      },
    ]);
  });

  it('covers prose and numbered requirements while leaving Scenario bodies to Scenario criteria', () => {
    const spec = `# Capability

Runtime preserves the current receipt graph.

1. Numbered requirements remain auditable.
2. Runtime MUST reject a stale receipt.

### Scenario: Stale receipt
- **WHEN** the receipt is stale
- **THEN** verification is blocked
`;
    const mandatory = deriveSpecMandatoryAcceptanceCriteria(spec);
    const scenarios = deriveSpecAcceptanceCriteria(spec);

    expect(mandatory.map((entry) => entry.text)).toEqual([
      'Runtime preserves the current receipt graph.',
      'Numbered requirements remain auditable.',
      'Runtime MUST reject a stale receipt.',
    ]);
    expect(mandatory.some((entry) => /WHEN|THEN/u.test(entry.text))).toBe(false);
    expect(scenarios).toHaveLength(1);
