  it('keeps the Scenario ID set stable when Scenario blocks are reordered', () => {
    const alpha = `### Scenario: Alpha
Alpha result.

### Scenario: Beta
Beta result.
`;
    const beta = `### Scenario: Beta
Beta result.

### Scenario: Alpha
Alpha result.
`;

